import{_ as r,o as e,c as o,a3 as t}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"转人工设置","description":"","frontmatter":{"title":"转人工设置"},"headers":[],"relativePath":"solution/transfer.md","filePath":"solution/transfer.md","lastUpdated":1787949005000}'),l={name:"solution/transfer.md"};function i(s,a,n,c,p,h){return e(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="转人工设置" tabindex="-1">转人工设置 <a class="header-anchor" href="#转人工设置" aria-label="Permalink to &quot;转人工设置&quot;">​</a></h1><p>AI 处理不了的问题要顺畅地交给人。转人工在<strong>店铺设置</strong>里配置（不在方案编辑器里）：同一店铺下的客服账号共用一套转接配置。</p><p>入口：「店铺客服」→ 点击店铺卡片 → 「转接客服」。</p><div class="warning custom-block"><p class="custom-block-title">闲鱼不支持转人工</p><p>闲鱼当前无法转人工。闲鱼店铺请关注客户端通知和<a href="/aicare-docs/workspace/records">聊天记录</a>里的待跟进会话。</p></div><h2 id="当前规则-按意图转接" tabindex="-1">当前规则：按意图转接 <a class="header-anchor" href="#当前规则-按意图转接" aria-label="Permalink to &quot;当前规则：按意图转接&quot;">​</a></h2><p>转接按「意图」组织。AI 判断顾客需要人工时，先归类到一个意图（比如售后、售前、投诉），再把会话转给该意图下配置的客服。</p><p>每个意图可以编辑：</p><ul><li><strong>名称</strong>：给自己看的标签。</li><li><strong>说明</strong>：给 AI 看的判断依据。写清楚什么样的问题算这个意图，AI 归类就更准。</li></ul><h2 id="给意图配置转接对象" tabindex="-1">给意图配置转接对象 <a class="header-anchor" href="#给意图配置转接对象" aria-label="Permalink to &quot;给意图配置转接对象&quot;">​</a></h2><p>每个意图下配置一个或多个转接客服：</p><ol><li>点击「同步转接对象」，把平台里已有的客服或客服组同步进来。</li><li>从「未分配客服」里选择客服，分配到对应意图。一个客服可以分配给多个意图。</li><li>用优先级滑杆排序：<strong>优先级数值大的先试</strong>，转不通（离线、转接失败）再试下一个。也可以直接拖拽调整顺序。</li></ol><p>需要手动添加平台账号时，添加后仍要等平台观测到该账号，才能确认它可用于转接。</p><p>注意：优先级是「先后顺序」，不是流量分配比例。想让两个客服分担压力，靠平台自身的分流，而不是这里。</p><h2 id="提示转人工不可用" tabindex="-1">提示转人工不可用 <a class="header-anchor" href="#提示转人工不可用" aria-label="Permalink to &quot;提示转人工不可用&quot;">​</a></h2><p>先检查这三项：</p><ol><li>当前接待的客服账号是否已经加入店铺，也就是接入位是否已绑定。</li><li>店铺里是否已经同步或添加了转接客服。</li><li>店铺里是否已经创建转接意图，并把客服分配给对应意图。</li></ol><p>缺少其中一项时，AI 仍可正常回复，但不能发起转人工。</p><h2 id="离线跟进" tabindex="-1">无人可接待跟进 <a class="header-anchor" href="#离线跟进" aria-label="Permalink to &quot;无人可接待跟进 {#离线跟进}&quot;">​</a></h2><p>当没有可用的转接对象时（都离线、或没配置），可以开启「无人可接待跟进」：系统记录这次转接，并给顾客发送一条跟进说明（最长 500 字），比如「客服暂时不在，看到后第一时间回复您」。</p><p>这类会话会进入聊天记录的<strong>待跟进</strong>筛选，记得每天清一遍。</p><h2 id="宽松转接" tabindex="-1">宽松转接 <a class="header-anchor" href="#宽松转接" aria-label="Permalink to &quot;宽松转接 {#宽松转接}&quot;">​</a></h2><p>客户端「设置 → 工作」里有「启用宽松转接」开关，<strong>默认开启</strong>：</p><ul><li>店铺没配转接对象、或配置的对象不在线、转接失败时，系统会尝试选择一个在线客服兜底转接（优先客服组），同时弹本地通知提醒你该店铺没有配置可用客服。</li><li>关闭后，上述情况直接按无人在线处理（走跟进说明或告知顾客没有客服在线）。</li></ul><p>建议保持开启，宁可转错人也不让顾客等。</p><h2 id="ai-什么时候转人工" tabindex="-1">AI 什么时候转人工 <a class="header-anchor" href="#ai-什么时候转人工" aria-label="Permalink to &quot;AI 什么时候转人工&quot;">​</a></h2><ul><li>AI 设置里开启了「转人工」工具，AI 判断需要人工时主动转，见 <a href="/aicare-docs/solution/agents">AI 设置与智能程度</a>。</li><li><a href="/aicare-docs/solution/general">通用配置</a>里的兜底回复默认是转人工：AI 无法正常回复时触发。</li><li>开启订单检测后，检测到顾客已下单也会转人工。</li><li><a href="/aicare-docs/solution/general#服务策略">夜间服务模式</a>时段内，转人工改为发送夜间话术。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>转接总是失败？</strong> 检查目标客服是否在线、手动添加的账号是否已被平台观测到。整体成功率可以在工作台的<a href="/aicare-docs/workspace/records#数据分析">数据分析</a>里看。</p><p><strong>想让某类问题必须转给固定的人？</strong> 把该意图下只配这一个对象，并在意图说明里写清判断标准。</p>',29)])])}const f=r(l,[["render",i]]);export{u as __pageData,f as default};
